WITH CONTRACT_STARTING_HEADCOUNT AS
(
	-- Contract starting headcount base set 1,488,153
    SELECT DISTINCT
		 pc.PLACEMENT_HKEY
		,pc._AIRBYTE_EXTRACTED_AT AS AIRBYTE_DATE
		,CAST(pc.START_DATE AS DATE) AS FACT_DATE_START
        ,CAST(pc.END_DATE AS DATE) AS FACT_DATE_END
		,dew.week_key AS EUROPEAN_WEEK_KEY
		,pc.CONTRACT_TYPE
        ,CASE WHEN pc.CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE pc.ELI_RECORD_TYPE_NAME__C END AS RECORD_TYPE
		,pc.DIVISION
		,pc.DOMAIN
		,pc.SEGMENT 
    FROM {{ ref('sat_bh4sf_placement_bvv_curr') }} pc
	JOIN {{ ref('dim_european_week') }} dew
		ON pc.START_DATE < dew.euro_start_day_of_week 
		AND (pc.END_DATE >= dew.euro_start_day_of_week OR pc.END_DATE IS NULL)
		AND YEAR(dew.euro_start_day_of_week) <= YEAR(CURRENT_DATE)+1
    WHERE pc.START_DATE IS NOT NULL
        AND pc.ISDELETED = 'N'
        AND pc.PLACEMENT_STATUS = 'Booked'
        AND CASE WHEN pc.CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE pc.ELI_RECORD_TYPE_NAME__C END IN ('Contract','Contract To Hire')
        AND UPPER(pc.ACCOUNT) NOT IN (
            SELECT COMPANY_BK FROM DEVROSS_INFOMART.INFOMART_EXCEPTION.COMPANY_EXCEPT
        )
    ORDER BY PLACEMENT_HKEY, EUROPEAN_WEEK_KEY
)
, CONTRACT_ENDING_HEADCOUNT AS
(
	-- Contract ending headcount base set
    SELECT DISTINCT
		 pc.PLACEMENT_HKEY
		,pc._AIRBYTE_EXTRACTED_AT AS AIRBYTE_DATE
		,CAST(pc.START_DATE AS DATE) AS FACT_DATE_START
        ,CAST(pc.END_DATE AS DATE) AS FACT_DATE_END
		,dew.week_key AS EUROPEAN_WEEK_KEY
		,pc.CONTRACT_TYPE
        ,CASE WHEN pc.CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE pc.ELI_RECORD_TYPE_NAME__C END AS RECORD_TYPE
		,pc.DIVISION
		,pc.DOMAIN
		,pc.SEGMENT
        ,pc.ISDELETED 
    FROM {{ ref('sat_bh4sf_placement_bvv_curr') }} pc
    --JOIN ELIASSEN_DW.ELI_DV_BV.HUB_PLACEMENT hp ON pc.PLACEMENT_HKEY = hp.PLACEMENT_HKEY
	JOIN {{ ref('dim_european_week') }} dew
		ON pc.START_DATE <= dew.euro_end_day_of_week 
		AND (pc.END_DATE > dew.euro_end_day_of_week OR pc.END_DATE IS NULL)
		AND YEAR(dew.euro_end_day_of_week) <= YEAR(CURRENT_DATE)+1
    WHERE pc.START_DATE IS NOT NULL
        AND pc.ISDELETED = 'N'
        AND pc.PLACEMENT_STATUS = 'Booked'
        AND CASE WHEN pc.CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE pc.ELI_RECORD_TYPE_NAME__C END IN ('Contract','Contract To Hire')
        AND UPPER(pc.ACCOUNT) NOT IN (
            SELECT COMPANY_BK FROM DEVROSS_INFOMART.INFOMART_EXCEPTION.COMPANY_EXCEPT
        )
        --AND hp.placement_bk = 'A0KUQ000008BKXPYAS'
    ORDER BY PLACEMENT_HKEY, EUROPEAN_WEEK_KEY
)
, CONSULTING_STARTING_HEADCOUNT AS
(
	-- Consulting starting headcount base set
    SELECT DISTINCT
        pc.PLACEMENT_HKEY
        ,pc._AIRBYTE_EXTRACTED_AT AS AIRBYTE_DATE
        ,CAST(pc.START_DATE AS DATE) AS FACT_DATE_START
        ,CAST(pc.END_DATE AS DATE) AS FACT_DATE_END
        ,dew.week_key AS EUROPEAN_WEEK_KEY
        ,pc.CONTRACT_TYPE
        ,CASE WHEN pc.CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE pc.ELI_RECORD_TYPE_NAME__C END AS RECORD_TYPE
        ,pc.DIVISION
        ,pc.DOMAIN
        ,pc.SEGMENT 
    FROM {{ ref('sat_bh4sf_placement_bvv_curr') }} pc
    JOIN {{ ref('dim_european_week') }} dew
        ON pc.START_DATE < dew.euro_start_day_of_week 
        AND (pc.END_DATE >= dew.euro_start_day_of_week OR pc.END_DATE IS NULL)
        AND YEAR(dew.euro_start_day_of_week) <= YEAR(CURRENT_DATE)+1
    WHERE START_DATE IS NOT NULL
        AND PC.ISDELETED = 'N'
        AND PLACEMENT_STATUS = 'Booked'
        AND CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END = 'Consulting'
        AND UPPER(pc.ACCOUNT) NOT IN (
            SELECT COMPANY_BK FROM DEVROSS_INFOMART.INFOMART_EXCEPTION.COMPANY_EXCEPT
        ) 
    ORDER BY PLACEMENT_HKEY, EUROPEAN_WEEK_KEY
)
, CONSULTING_ENDING_HEADCOUNT AS
(
	-- Consulting ending headcount base set
    SELECT DISTINCT
        pc.PLACEMENT_HKEY
        ,pc._AIRBYTE_EXTRACTED_AT AS AIRBYTE_DATE
        ,CAST(pc.START_DATE AS DATE) AS FACT_DATE_START
        ,CAST(pc.END_DATE AS DATE) AS FACT_DATE_END
        ,dew.week_key AS EUROPEAN_WEEK_KEY
        ,pc.CONTRACT_TYPE
        ,CASE WHEN pc.CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE pc.ELI_RECORD_TYPE_NAME__C END AS RECORD_TYPE
        ,pc.DIVISION
        ,pc.DOMAIN
        ,pc.SEGMENT 
    FROM {{ ref('sat_bh4sf_placement_bvv_curr') }} pc
    JOIN {{ ref('dim_european_week') }} dew
        ON pc.START_DATE <= dew.euro_end_day_of_week 
		AND (pc.END_DATE > dew.euro_end_day_of_week OR pc.END_DATE IS NULL)
		AND YEAR(dew.euro_end_day_of_week) <= YEAR(CURRENT_DATE)+1
    WHERE START_DATE IS NOT NULL
        AND PC.ISDELETED = 'N'
        AND PLACEMENT_STATUS = 'Booked'
        AND CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END = 'Consulting'
        AND UPPER(pc.ACCOUNT) NOT IN (
            SELECT COMPANY_BK FROM DEVROSS_INFOMART.INFOMART_EXCEPTION.COMPANY_EXCEPT
        ) 
    ORDER BY PLACEMENT_HKEY, EUROPEAN_WEEK_KEY
)
, TOTAL_STARTING_HEADCOUNT AS
(
	-- Total starting headcount base set
    SELECT DISTINCT
		 PLACEMENT_HKEY
		,_AIRBYTE_EXTRACTED_AT AS AIRBYTE_DATE
		,CAST(START_DATE AS DATE) AS FACT_DATE_START
        ,CAST(END_DATE AS DATE) AS FACT_DATE_END
        ,dew.week_key AS EUROPEAN_WEEK_KEY
		,CONTRACT_TYPE
        ,CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END AS RECORD_TYPE
		,DIVISION
		,DOMAIN
		,SEGMENT 
    FROM {{ ref('sat_bh4sf_placement_bvv_curr') }} pc
    JOIN {{ ref('dim_european_week') }} dew
        ON pc.START_DATE < dew.euro_start_day_of_week 
        AND (pc.END_DATE >= dew.euro_start_day_of_week OR pc.END_DATE IS NULL)
        AND YEAR(dew.euro_start_day_of_week) <= YEAR(CURRENT_DATE)+1
    WHERE START_DATE IS NOT NULL
        AND PC.ISDELETED = 'N'
        AND PLACEMENT_STATUS = 'Booked'
        AND CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END IN ('Contract','Contract To Hire','Consulting')
        AND UPPER(pc.ACCOUNT) NOT IN (
            SELECT COMPANY_BK FROM DEVROSS_INFOMART.INFOMART_EXCEPTION.COMPANY_EXCEPT
        ) 
    ORDER BY PLACEMENT_HKEY, EUROPEAN_WEEK_KEY
)
, TOTAL_ENDING_HEADCOUNT AS
(
	-- Total ending headcount base set
    SELECT DISTINCT
		 PLACEMENT_HKEY
		,_AIRBYTE_EXTRACTED_AT AS AIRBYTE_DATE
		,CAST(START_DATE AS DATE) AS FACT_DATE_START
        ,CAST(END_DATE AS DATE) AS FACT_DATE_END
        ,dew.week_key AS EUROPEAN_WEEK_KEY
		,CONTRACT_TYPE
        ,CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END AS RECORD_TYPE
		,DIVISION
		,DOMAIN
		,SEGMENT 
    FROM {{ ref('sat_bh4sf_placement_bvv_curr') }} pc
    JOIN {{ ref('dim_european_week') }} dew
        ON pc.START_DATE <= dew.euro_end_day_of_week 
		AND (pc.END_DATE > dew.euro_end_day_of_week OR pc.END_DATE IS NULL)
		AND YEAR(dew.euro_end_day_of_week) <= YEAR(CURRENT_DATE)+1
    WHERE START_DATE IS NOT NULL
        AND PC.ISDELETED = 'N'
        AND PLACEMENT_STATUS = 'Booked'
        AND CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END IN ('Contract','Contract To Hire','Consulting')
        AND UPPER(pc.ACCOUNT) NOT IN (
            SELECT COMPANY_BK FROM DEVROSS_INFOMART.INFOMART_EXCEPTION.COMPANY_EXCEPT
        ) 
    ORDER BY PLACEMENT_HKEY, EUROPEAN_WEEK_KEY
)
, FACT_DATE_CTE AS
(
	-- Fact date base set
	SELECT PLACEMENT_HKEY, 
        -- AIRBYTE_DATE, FACT_DATE_START, FACT_DATE_END, 
        EUROPEAN_WEEK_KEY, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
	FROM CONTRACT_STARTING_HEADCOUNT
	UNION
	SELECT PLACEMENT_HKEY, 
        -- AIRBYTE_DATE, FACT_DATE_START, FACT_DATE_END, 
        EUROPEAN_WEEK_KEY, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
	FROM CONTRACT_ENDING_HEADCOUNT
	UNION
	SELECT PLACEMENT_HKEY, 
        -- AIRBYTE_DATE, FACT_DATE_START, FACT_DATE_END, 
        EUROPEAN_WEEK_KEY, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
	FROM CONSULTING_STARTING_HEADCOUNT
    UNION
    SELECT PLACEMENT_HKEY, 
        -- AIRBYTE_DATE, FACT_DATE_START, FACT_DATE_END, 
        EUROPEAN_WEEK_KEY, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
	FROM CONSULTING_ENDING_HEADCOUNT
	UNION
	SELECT PLACEMENT_HKEY, 
        -- AIRBYTE_DATE, FACT_DATE_START, FACT_DATE_END, 
        EUROPEAN_WEEK_KEY, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
	FROM TOTAL_STARTING_HEADCOUNT
	UNION
	SELECT PLACEMENT_HKEY, 
        -- AIRBYTE_DATE, FACT_DATE_START, FACT_DATE_END, 
        EUROPEAN_WEEK_KEY, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
	FROM TOTAL_ENDING_HEADCOUNT
    ORDER BY PLACEMENT_HKEY, EUROPEAN_WEEK_KEY
)
SELECT 
      FD.PLACEMENT_HKEY
    -- , FD.AIRBYTE_DATE
    -- , FD.FACT_DATE_START
    -- , FD.FACT_DATE_END
    ,FD.EUROPEAN_WEEK_KEY
    , CAST(SUM(CASE WHEN CONTRACT_STARTING_HEADCOUNT.EUROPEAN_WEEK_KEY IS NOT NULL THEN
					CASE WHEN CONTRACT_STARTING_HEADCOUNT.CONTRACT_TYPE = 'Part-Time' THEN 0.5 ELSE 1 END
				ELSE 0 END) AS DECIMAL(10,1)) AS CONTRACT_STARTING_HEADCOUNT
	, CAST(SUM(CASE WHEN CONTRACT_ENDING_HEADCOUNT.EUROPEAN_WEEK_KEY IS NOT NULL THEN
					CASE WHEN CONTRACT_ENDING_HEADCOUNT.CONTRACT_TYPE = 'Part-Time' THEN 0.5 ELSE 1 END
				ELSE 0 END) AS DECIMAL(10,1)) AS CONTRACT_ENDING_HEADCOUNT
	, CAST(SUM(CASE WHEN CONSULTING_STARTING_HEADCOUNT.EUROPEAN_WEEK_KEY IS NOT NULL THEN
					CASE WHEN CONSULTING_STARTING_HEADCOUNT.CONTRACT_TYPE = 'Part-Time' THEN 0.5 ELSE 1 END
				ELSE 0 END) AS DECIMAL(10,1)) AS CONSULTING_STARTING_HEADCOUNT
    , CAST(SUM(CASE WHEN CONSULTING_ENDING_HEADCOUNT.EUROPEAN_WEEK_KEY IS NOT NULL THEN
					CASE WHEN CONSULTING_ENDING_HEADCOUNT.CONTRACT_TYPE = 'Part-Time' THEN 0.5 ELSE 1 END
				ELSE 0 END) AS DECIMAL(10,1)) AS CONSULTING_ENDING_HEADCOUNT
	, CAST(SUM(CASE WHEN TOTAL_STARTING_HEADCOUNT.EUROPEAN_WEEK_KEY IS NOT NULL THEN
					CASE WHEN TOTAL_STARTING_HEADCOUNT.CONTRACT_TYPE = 'Part-Time' THEN 0.5 ELSE 1 END
				ELSE 0 END) AS DECIMAL(10,1)) AS TOTAL_STARTING_HEADCOUNT
	, CAST(SUM(CASE WHEN TOTAL_ENDING_HEADCOUNT.EUROPEAN_WEEK_KEY IS NOT NULL THEN
					CASE WHEN TOTAL_ENDING_HEADCOUNT.CONTRACT_TYPE = 'Part-Time' THEN 0.5 ELSE 1 END
				ELSE 0 END) AS DECIMAL(10,1)) AS TOTAL_ENDING_HEADCOUNT
    , FD.RECORD_TYPE
    , FD.DIVISION
    , FD.DOMAIN
    , FD.SEGMENT
FROM FACT_DATE_CTE FD
LEFT JOIN CONTRACT_STARTING_HEADCOUNT
ON FD.PLACEMENT_HKEY = CONTRACT_STARTING_HEADCOUNT.PLACEMENT_HKEY AND FD.EUROPEAN_WEEK_KEY = CONTRACT_STARTING_HEADCOUNT.EUROPEAN_WEEK_KEY
LEFT JOIN CONTRACT_ENDING_HEADCOUNT
ON FD.PLACEMENT_HKEY = CONTRACT_ENDING_HEADCOUNT.PLACEMENT_HKEY AND FD.EUROPEAN_WEEK_KEY = CONTRACT_ENDING_HEADCOUNT.EUROPEAN_WEEK_KEY
LEFT JOIN CONSULTING_STARTING_HEADCOUNT
ON FD.PLACEMENT_HKEY = CONSULTING_STARTING_HEADCOUNT.PLACEMENT_HKEY AND FD.EUROPEAN_WEEK_KEY = CONSULTING_STARTING_HEADCOUNT.EUROPEAN_WEEK_KEY
LEFT JOIN CONSULTING_ENDING_HEADCOUNT
ON FD.PLACEMENT_HKEY = CONSULTING_ENDING_HEADCOUNT.PLACEMENT_HKEY AND FD.EUROPEAN_WEEK_KEY = CONSULTING_ENDING_HEADCOUNT.EUROPEAN_WEEK_KEY
LEFT JOIN TOTAL_STARTING_HEADCOUNT
ON FD.PLACEMENT_HKEY = TOTAL_STARTING_HEADCOUNT.PLACEMENT_HKEY AND FD.EUROPEAN_WEEK_KEY = TOTAL_STARTING_HEADCOUNT.EUROPEAN_WEEK_KEY
LEFT JOIN TOTAL_ENDING_HEADCOUNT
ON FD.PLACEMENT_HKEY = TOTAL_ENDING_HEADCOUNT.PLACEMENT_HKEY AND FD.EUROPEAN_WEEK_KEY = TOTAL_ENDING_HEADCOUNT.EUROPEAN_WEEK_KEY
GROUP BY
     FD.PLACEMENT_HKEY
    -- , FD.AIRBYTE_DATE
    -- , FD.FACT_DATE_START
    -- , FD.FACT_DATE_END
     ,FD.EUROPEAN_WEEK_KEY
    , FD.RECORD_TYPE
    , FD.DIVISION
    , FD.DOMAIN
    , FD.SEGMENT